import {currentUser,supabase} from './auth-client.mjs';
import {loadRoster,saveRoster} from './my-tatari-client.mjs';
import {emptyRoster,validateRoster,starCost,foodGrade,sortRosterUnits,rosterPortrait,hasGlitter,rosterTier} from './my-tatari-model.mjs?v=tier-map2';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n},root=new URL('./tatari-data/',import.meta.url);let catalog,state=emptyRoster(),actor='preview',selected=null,rosterView='all',generation=0,cloudRevision=0,ready=false,saving=false;
function defaults(u){return {owned:false,tier:u.forms[0].evolution,stars:1,food:u.feedingStages[0].stage,copies:0,glitter:false}}
function image(src,alt,cls){const n=el('img',undefined,cls);n.src=new URL(src,root);n.alt=alt;n.loading='lazy';return n}
function status(text){$('roster-status').textContent=text}
async function persist(next){if(!ready||saving||actor==='preview')return false;const token=generation,id=actor;saving=true;for(const b of document.querySelectorAll('#roster-edit-form button[type=submit],#roster-level-save'))b.disabled=true;try{const result=await saveRoster(id,validateRoster(next,catalog),cloudRevision);if(token!==generation||actor!==id)return false;state=validateRoster(result.roster,catalog);cloudRevision=result.revision;return true}catch(e){if(token===generation)status(e.message);return false}finally{if(token===generation){saving=false;for(const b of document.querySelectorAll('#roster-edit-form button[type=submit],#roster-level-save'))b.disabled=false}}}
function card(u,v,preview=false){const f=u.forms.find(f=>f.evolution===v.tier)||u.forms[0],wrap=el(preview?'div':'button',undefined,'roster-item'+(!v.owned&&!preview?' not-owned':''));if(!preview){wrap.type='button';wrap.setAttribute('aria-label',f.name.en+', '+(v.owned?'owned':'not owned')+', edit settings');wrap.onclick=()=>open(u)}const art=el('div',undefined,'roster-art');art.append(image('images/tier-'+rosterTier(u,f.evolution)+'.png','','roster-frame'),image(rosterPortrait(u,v,catalog),f.name.en+(v.glitter&&hasGlitter(u,v.tier,catalog)?' · Glitter':''),'roster-portrait'));art.append(el('span','Lvl '+state.accountLevel,'roster-level'));const grade=foodGrade(u,v.food,catalog),badge=image('food-grades/'+grade.RankName+'.png?v=grade-refresh7','Food grade '+grade.RankName,'roster-food-grade');badge.dataset.grade=grade.RankName;art.append(badge);const icons=el('div',undefined,'roster-icons');icons.append(image(u.elementImage,'Element'),image(u.roleImage,u.role.en));art.append(icons,image('stars/'+String(v.stars).padStart(2,'0')+'.png',v.stars+' stars','roster-star-art'));if(!v.owned&&!preview)art.append(el('span','Not owned','roster-unowned'));wrap.append(art);const cost=starCost(v.stars,catalog),copies=v.copies??0,progress=el('div',undefined,'roster-food-track'),fill=el('span');fill.style.width=(cost?Math.min(100,copies/cost*100):100)+'%';progress.append(fill,el('small',cost?copies+' / '+cost:'MAX'));progress.setAttribute('aria-label',cost?copies+' of '+cost+' copies toward next star':'Maximum star level');wrap.append(progress,el('span',f.name.en,'roster-name'),el('span','Food '+v.food+(v.glitter?' · Glitter':''),'roster-card-detail'));return wrap}
function render(){if(!catalog||!ready||actor==='preview')return;$('roster-level').value=state.accountLevel;$('roster-count').textContent=Object.values(state.units).filter(v=>v.owned).length+' / '+catalog.units.length+' owned';const query=$('roster-search').value.trim().toLowerCase();const rows=sortRosterUnits(catalog.units,state.units).filter(u=>(rosterView==='all'||(rosterView==='owned'?state.units[u.id]?.owned:!state.units[u.id]?.owned))&&(!query||u.forms.some(f=>f.name.en.toLowerCase().includes(query))||u.internalName.toLowerCase().includes(query)));$('roster-grid').replaceChildren(...rows.map(u=>card(u,state.units[u.id]||defaults(u))));$('roster-empty').hidden=rows.length>0;$('roster-all').setAttribute('aria-pressed',String(rosterView==='all'));$('roster-owned').setAttribute('aria-pressed',String(rosterView==='owned'));$('roster-unowned').setAttribute('aria-pressed',String(rosterView==='unowned'))}
function editorValue(){return {owned:$('roster-is-owned').checked,tier:Number($('roster-tier').value),stars:Number($('roster-stars').value),food:Number($('roster-food').value),copies:Number($('roster-copies').value),glitter:$('roster-glitter').checked}}
function copyOptions(stars,copies=0){const cost=starCost(stars,catalog);$('roster-copies').replaceChildren(...Array.from({length:Math.max(1,cost||0)},(_,i)=>new Option(cost?i+' / '+cost+' copies':'Maximum star level',i)));$('roster-copies').value=String(Math.min(copies,Math.max(0,(cost||0)-1)));$('roster-copies').disabled=!cost}
function updatePreview(){if(!selected)return;const v=editorValue();$('roster-glitter').disabled=!hasGlitter(selected,v.tier,catalog)&&!v.glitter;$('roster-glitter').title=hasGlitter(selected,v.tier,catalog)?'':'Glitter artwork is not available for this tier.';$('roster-star-picker').replaceChildren(image('stars/'+String(v.stars).padStart(2,'0')+'.png',v.stars+' stars'),el('span',v.stars+' stars'));const f=selected.forms.find(f=>f.evolution===v.tier);$('roster-editor-title').textContent=f.name.en;$('roster-modal-preview').replaceChildren(card(selected,v,true));$('roster-modal-level').textContent='Level '+state.accountLevel+' · follows your account level.'}
function open(u){if(!ready||saving||actor==='preview')return;selected=u;const v=state.units[u.id]||defaults(u);$('roster-tier').replaceChildren(...u.forms.map(f=>new Option('Tier '+rosterTier(u,f.evolution)+' · '+f.name.en,f.evolution)));$('roster-food').replaceChildren(...u.feedingStages.map(f=>new Option('Food level '+f.stage,f.stage)));$('roster-is-owned').checked=v.owned;$('roster-tier').value=v.tier;$('roster-stars').value=v.stars;$('roster-food').value=v.food;$('roster-glitter').checked=v.glitter??false;copyOptions(v.stars,v.copies??0);$('roster-edit-error').textContent='';updatePreview();$('roster-editor').showModal()}
async function loadActor(){const token=++generation;ready=false;saving=false;selected=null;document.querySelector('.roster-star-dialog')?.close();$('roster-editor').close();$('roster-grid').replaceChildren();$('roster-level').disabled=$('roster-level-save').disabled=true;state=emptyRoster();cloudRevision=0;try{const user=await currentUser();if(token!==generation)return;actor=user?.id||'preview';if(!user){document.querySelector('.roster-local-note').textContent='Log in to manage your Tatari';status('Log in from My Account to set up your Tatari.');return}status('Loading your Tatari…');const row=await loadRoster(actor);if(token!==generation)return;state=row?validateRoster(row.roster,catalog):emptyRoster();cloudRevision=row?.revision||0;document.querySelector('.roster-local-note').textContent='Private · saved to your account';status('');ready=true;$('roster-level').disabled=$('roster-level-save').disabled=false;render()}catch(e){if(token===generation)status('Could not load your Tatari. '+e.message)}}
$('roster-edit-form').onsubmit=async event=>{event.preventDefault();const token=generation,user=await currentUser();if(token!==generation||(user?.id||'preview')!==actor){$('roster-edit-error').textContent='Your account changed. Reopen the Tatari to continue.';return}const next=structuredClone(state);next.units[selected.id]=editorValue();if(await persist(next)){render();$('roster-editor').close();status('Tatari saved to your account.')}else $('roster-edit-error').textContent=$('roster-status').textContent||'Save failed. Your changes are still open.'};$('roster-cancel').onclick=()=>$('roster-editor').close();for(const id of ['roster-tier','roster-food','roster-is-owned','roster-copies'])$(id).onchange=updatePreview;
$('roster-stars').onchange=()=>{copyOptions(Number($('roster-stars').value),Number($('roster-copies').value));updatePreview()};for(const id of ['roster-glitter'])$(id).onchange=()=>{if($(id).checked)$('roster-is-owned').checked=true;updatePreview()};
$('roster-level-save').onclick=async()=>{const token=generation,user=await currentUser();if(token!==generation||(user?.id||'preview')!==actor){status('Your account changed. Please try again.');return}const level=Number($('roster-level').value);if(!Number.isInteger(level)||level<1||level>99999){status('Enter a whole account level from 1 to 99,999.');return}if(await persist({...state,accountLevel:level})){render();status('Account level saved. All Tatari levels updated.')}};
$('roster-all').onclick=()=>{rosterView='all';render()};$('roster-owned').onclick=()=>{rosterView='owned';render()};$('roster-unowned').onclick=()=>{rosterView='unowned';render()};$('roster-search').oninput=render;
try{const response=await fetch(new URL('roster.json',root));if(!response.ok)throw Error('Tatari catalog unavailable');catalog=await response.json();const progressResponse=await fetch(new URL('star-progression.json',root));if(!progressResponse.ok)throw Error('Star progression unavailable');catalog.starProgression=await progressResponse.json();const portraitsResponse=await fetch(new URL('portrait-index.json',root));if(!portraitsResponse.ok)throw Error('Tatari appearance catalog unavailable');catalog.portraits=(await portraitsResponse.json()).images;await loadActor();supabase.auth.onAuthStateChange(event=>{if(event!=='TOKEN_REFRESHED')setTimeout(loadActor,0)})}catch(e){status(e.message);$('roster-level').disabled=true}

const starDialog=el('dialog',undefined,'roster-star-dialog');starDialog.setAttribute('aria-label','Choose star level');const starHead=el('div',undefined,'roster-star-heading'),starClose=el('button','×');starClose.type='button';starClose.setAttribute('aria-label','Close star selection');starClose.onclick=()=>starDialog.close();starHead.append(el('h2','Choose star level'),starClose);starDialog.append(starHead,el('p','Choose the star image that matches your Tatari.'));const starGrid=el('div',undefined,'roster-star-grid');for(let n=1;n<=84;n++){const b=el('button');b.type='button';b.setAttribute('aria-label',n+' stars');b.dataset.stars=n;b.append(image('stars/'+String(n).padStart(2,'0')+'.png',n+' stars'));b.onclick=()=>{$('roster-stars').value=String(n);$('roster-stars').onchange();starDialog.close()};starGrid.append(b)}starDialog.append(starGrid);document.body.append(starDialog);$('roster-star-picker').onclick=()=>{for(const b of starGrid.children)b.setAttribute('aria-pressed',String(b.dataset.stars===$('roster-stars').value));starDialog.showModal()};

$('roster-refresh').onclick=()=>{if(!saving)loadActor()};
